import os
import asyncio
from lib import L
async def main():
    s=L();await s.start('install');W=s.pg.wait_for_timeout
    await s.click('app:term');await s.type('ip route');await s.type('cat /etc/resolv.conf')
    await s.type('ping 192.168.0.201');await s.click('app:ipam');await s.click('reserve:201')
    await s.click('app:plan');await s.click('review');await s.step('planning',3)
    await s.click('app:browser');await s.type('proxmox.com/en/downloads','#url');await s.click('dl:ve');await W(2800);await s.step('download',4)
    await s.click('usb:laptop');await s.click('app:usb');print('  usb writer acts',[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    print('  selects',await s.pg.evaluate("[...document.querySelectorAll('#wiz select')].map(e=>[e.dataset.ik||e.dataset.k||e.id,[...e.options].map(o=>o.value)])"))
    await s.pg.select_option('#wiz select','proxmox-ve_9.2-1.iso');await s.click('flash');await W(2800);await s.step('flash',5)
    print('  after flash acts',[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    await s.click('usb:pocket')
    await s.click('go:room');await s.click('rk:open')
    await s.drag('[data-drag="rails"] rect','[data-drop="2"] rect');await s.drag('[data-drag="server"] rect','[data-drop="2"] rect')
    await s.click('rk:kind:power');await s.drag('[data-port="psu1"] rect','[data-port="A3"] rect');await s.drag('[data-port="psu2"] rect','[data-port="B3"] rect');await s.step('mount+power',6)
    await s.click('rk:kind:net');await s.drag('[data-port="eno1"] rect','[data-port="P3"] rect');await s.step('network cable',7)
    await s.pg.click('.addm summary');await s.click('rk:add:trol');await s.click('rk:kind:console');await s.drag('[data-port="scr"] rect','[data-port="trol"] rect')
    await s.click('rk:kind:hands');await s.click('power');print('  room acts',[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))], await s.pg.evaluate("LAB.W().inst.screen"))
    await s.click('key:F2');print('  bios acts',[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    await s.click('vt');await s.click('biosexit');await s.step('bios',8)
    await s.click('usb:server');await s.click('key:F11');print('  bootmenu acts',[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    await s.click('boot:usb');await s.click('inst:gui');await s.click('eula');await s.step('boot into installer',9)
    async def fields(): return await s.pg.evaluate("[...document.querySelectorAll('#wiz select,#wiz input')].map(e=>[e.tagName,e.dataset.k||e.id,e.value,e.tagName=='SELECT'?[...e.options].map(o=>o.value):e.type])")
    print('  wizard 1',await fields(),[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    await s.pg.select_option('[data-k="fs"]','zfs (RAID1)');await W(100);print('  after fs',await fields())
    await s.pg.select_option('[data-k="d0"]','sda');await s.pg.select_option('[data-k="d1"]','sdb');await s.step('mirror',10)
    await s.click('wnext');print('  wizard 2',await fields());await s.pg.screenshot(path=os.path.join(os.path.dirname(os.path.abspath(__file__)),'last.png'))
    await s.pg.fill('[data-k="country"]','Belgium')
    await s.click('wnext');print('  wizard 3',await fields(),await s.msg())
    for k,v in [('pw','Geheim-2026'),('pw2','Geheim-2026'),('mail','k@lab.be')]: await s.pg.fill(f'[data-k="{k}"]',v)
    await s.click('wnext');print('  wizard 4',await fields(),await s.msg())
    for k,v in [('host','pve1.lab.local'),('ip','192.168.0.201/24'),('gw','192.168.0.1'),('dns','192.168.0.10')]: await s.pg.fill(f'[data-k="{k}"]',v)
    await s.step('network settings',11)
    await s.click('wnext');print('  wizard 5',(await s.pg.inner_text('#wiz'))[-420:].replace('\n',' | '))
    await s.click('wnext');await W(3000);print('  after install',await s.pg.evaluate("LAB.W().inst.screen"),[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    await s.click('usb:pocket');await s.click('reboot');await W(300);print('  after reboot',await s.pg.evaluate("LAB.W().inst.screen"),[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))])
    await s.click('key:wait');await s.step('finish install',12)
    print('  screen text',(await s.pg.inner_text('#wiz'))[-300:].replace('\n',' | '))
    await s.click('go:desk');await s.click('app:term');await s.type('ssh root@192.168.0.201');await s.type('yes');await s.type('Geheim-2026');await s.step('ssh login',13)
    await s.type('hostname');await s.step('hostname',14)
    await s.click('app:browser');await s.type('https://192.168.0.201:8006','#url');print('  web acts',[a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))]);await s.pg.screenshot(path=os.path.join(os.path.dirname(os.path.abspath(__file__)),'last.png'))
    async def web(): return [a for a in await s.acts('#wiz') if not a.startswith(('app:','go:'))], await s.pg.evaluate("[...document.querySelectorAll('#wiz select,#wiz input')].filter(e=>e.getBoundingClientRect().width>0).map(e=>[e.tagName,e.id||e.dataset.k||e.dataset.ik||e.name,e.value,e.tagName=='SELECT'?[...e.options].map(o=>o.value):e.type])")
    await s.click('pveadv');print('  adv',await web())
    await s.click('pveproceed');print('  login',await web());await s.pg.screenshot(path=os.path.join(os.path.dirname(os.path.abspath(__file__)),'last.png'))
    await s.pg.fill('#pveu','Root');await s.pg.fill('#pvep','Geheim-2026');await s.click('pvego');print('  wrong user ->',(await s.pg.inner_text('#wiz'))[-160:].replace('\n',' | '))
    await s.pg.fill('#pveu','root');await s.pg.fill('#pvep','Geheim-2026');await s.click('pvego');await s.step('web login',15);print('  in',await web())
    await s.click('pvesel:node');print('  node click before OK ->',(await web())[0]);
    await s.click('pvesub');await s.click('pvesel:node');print('  node',(await web())[0])
    await s.click('pvetab:net');await s.step('find the bridge',-1);await s.pg.screenshot(path=os.path.join(os.path.dirname(os.path.abspath(__file__)),'last.png'))
    print('  done box',(await s.pg.inner_text('#left'))[-260:].replace(chr(10),' | '))
    await s.stop()
asyncio.run(main())
